    }
    if (base->len == 1 && base->d[0] == 0) {
        bi_free(result);
        return bi_new();
    }

    BigInt *b = bi_copy(base);
    while (exp != 0) {
        if (exp & 1ULL) {
            BigInt *t = bi_mul(result, b);
            bi_free(result);
            result = t;
        }
        exp >>= 1ULL;
        if (exp != 0) {
            BigInt *t = bi_mul(b, b);
            bi_free(b);
            b = t;
        }
    }
    bi_free(b);
    return result;
