} BigInt;

BigInt* bi_new(void) {
    BigInt *a = (BigInt*)malloc(sizeof(BigInt));
    if (!a) exit(1);
    a->d = (uint32_t*)malloc(sizeof(uint32_t));
    if (!a->d) exit(1);
    a->d[0] = 0;
    a->len = 1;
    return a;
}

void bi_free(BigInt *a) {
    if (a) {
        free(a->d);
        free(a);
    }
}

void bi_trim(BigInt *a) {
    while (a->len > 1 && a->d[a->len - 1] == 0) {
        a->len--;
    }
}

BigInt* bi_copy(const BigInt *a) {
    BigInt *b = bi_new();
    b->len = a->len;
    b->d = (uint32_t*)malloc(a->len * sizeof(uint32_t));
    if (!b->d) exit(1);
    for (size_t i = 0; i < a->len; i++) {
        b->d[i] = a->d[i];
    }
    return b;
}

void bi_set_u64(BigInt *a, unsigned long long x) {
    free(a->d);
