    if (!a->d) exit(1);
    size_t len = 0;
    do {
        a->d[len++] = (uint32_t)(x % BASE);
        x /= BASE;
    } while (x != 0);
    a->len = len;
}

BigInt* bi_mul(const BigInt *a, const BigInt *b) {
    if ((a->len == 1 && a->d[0] == 0) || (b->len == 1 && b->d[0] == 0)) {
        return bi_new();
    }

    size_t max = a->len + b->len;
    BigInt *r = (BigInt*)malloc(sizeof(BigInt));
    if (!r) exit(1);
