            uint64_t cur = (uint64_t)r->d[i + j]
                         + (uint64_t)a->d[i] * (uint64_t)b->d[j]
                         + carry;
            r->d[i + j] = (uint32_t)(cur % BASE);
            carry = cur / BASE;
        }

