#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define BASE 1000000000u

typedef struct {
    uint32_t *d;
    size_t len;
} BigInt;

BigInt* bi_new(void) {
    BigInt *a = (BigInt*)malloc(sizeof(BigInt));
    if (!a) exit(1);
    a->d = (uint32_t*)malloc(sizeof(uint32_t));
    if (!a->d) exit(1);
    a->d[0] = 0;
    a->len = 1;
    return a;
}

void bi_free(BigInt *a) {
    if (a) {
        free(a->d);
        free(a);
    }
}

void bi_trim(BigInt *a) {
    while (a->len > 1 && a->d[a->len - 1] == 0) {
        a->len--;
    }
}

BigInt* bi_copy(const BigInt *a) {
    BigInt *b = (BigInt*)malloc(sizeof(BigInt));
    if (!b) exit(1);
    b->len = a->len;
    b->d = (uint32_t*)malloc(a->len * sizeof(uint32_t));
    if (!b->d) exit(1);
    for (size_t i = 0; i < a->len; i++) {
        b->d[i] = a->d[i];
    }
    return b;
}

void bi_set_u64(BigInt *a, unsigned long long x) {
    free(a->d);
    a->d = (uint32_t*)malloc(4 * sizeof(uint32_t));
    if (!a->d) exit(1);
    size_t len = 0;
    do {
        a->d[len++] = (uint32_t)(x % BASE);
        x /= BASE;
    } while (x != 0);
    a->len = len;
}

BigInt* bi_mul(const BigInt *a, const BigInt *b) {
    if ((a->len == 1 && a->d[0] == 0) || (b->len == 1 && b->d[0] == 0)) {
        return bi_new();
    }

    size_t max = a->len + b->len;
    BigInt *r = (BigInt*)malloc(sizeof(BigInt));
    if (!r) exit(1);
    r->d = (uint32_t*)calloc(max + 1, sizeof(uint32_t));
    if (!r->d) exit(1);
    r->len = max + 1;

    for (size_t i = 0; i < a->len; i++) {
        uint64_t carry = 0;
        for (size_t j = 0; j < b->len; j++) {
            uint64_t cur = (uint64_t)r->d[i + j]
                         + (uint64_t)a->d[i] * (uint64_t)b->d[j]
                         + carry;
            r->d[i + j] = (uint32_t)(cur % BASE);
            carry = cur / BASE;
        }

        size_t idx = i + b->len;
        while (carry != 0) {
            uint64_t cur = (uint64_t)r->d[idx] + carry;
            r->d[idx] = (uint32_t)(cur % BASE);
            carry = cur / BASE;
            idx++;
        }
    }

    bi_trim(r);
    return r;
}

BigInt* bi_add(const BigInt *a, const BigInt *b) {
    size_t max = (a->len > b->len) ? a->len : b->len;
    BigInt *r = (BigInt*)malloc(sizeof(BigInt));
    if (!r) exit(1);
    r->d = (uint32_t*)calloc(max + 1, sizeof(uint32_t));
    if (!r->d) exit(1);
    r->len = max + 1;

    uint64_t carry = 0;
    for (size_t i = 0; i < max; i++) {
        uint64_t x = (i < a->len) ? a->d[i] : 0;
        uint64_t y = (i < b->len) ? b->d[i] : 0;
        uint64_t cur = x + y + carry;
        r->d[i] = (uint32_t)(cur % BASE);
        carry = cur / BASE;
    }
    if (carry != 0) {
        r->d[max] = (uint32_t)carry;
    }

    bi_trim(r);
    return r;
}

BigInt* bi_pow(const BigInt *base, unsigned long long exp) {
    BigInt *result = bi_new();
    result->d[0] = 1;

    if (exp == 0) {
        return result;
    }
    if (base->len == 1 && base->d[0] == 1) {
        return result;
    }
    if (base->len == 1 && base->d[0] == 0) {
        bi_free(result);
        return bi_new();
    }

    BigInt *b = bi_copy(base);
    while (exp != 0) {
        if (exp & 1ULL) {
            BigInt *t = bi_mul(result, b);
            bi_free(result);
            result = t;
        }
        exp >>= 1ULL;
        if (exp != 0) {
            BigInt *t = bi_mul(b, b);
            bi_free(b);
            b = t;
        }
    }
    bi_free(b);
    return result;
}

void bi_print(const BigInt *a) {
    printf("%lu", (unsigned long)a->d[a->len - 1]);
    for (size_t i = a->len - 1; i > 0; i--) {
        printf("%09lu", (unsigned long)a->d[i - 1]);
    }
}

int main(void) {
