        if (un % 2ULL == 0) {
            a = un / 2ULL;
            b = un + 1ULL;
        } else {
            a = un;
            b = (un + 1ULL) / 2ULL;
        }

        BigInt *x = bi_new();
        BigInt *y = bi_new();
        bi_set_u64(x, a);
        bi_set_u64(y, b);

        BigInt *sum = bi_mul(x, y);
        bi_free(x);
        bi_free(y);

        bi_print(sum);
        puts("");
        bi_free(sum);
        return 0;
    }

    if (k == 2) {
        unsigned long long x = un;
        unsigned long long y = un + 1ULL;
        unsigned long long z = 2ULL * un + 1ULL;

        if (x % 2ULL == 0) {
