    if (scanf("%lf %lf %lf %lf %lf", &a, &b, &c, &d, &k) != 5) {
        return 0;
    }

    double A = a;
    double B = b - d;
    double C = c - k;

    if (A == 0.0) {
        if (B == 0.0) {
            printf("no roots\n");
        } else {
            double x = -C / B;
            printf("%.6f\n", fix_zero(x));
        }
        return 0;
    }

    double D = B * B - 4.0 * A * C;
    double scale = 1.0;
    double v1 = fabs(B * B);
    double v2 = fabs(4.0 * A * C);
    if (v1 > scale) scale = v1;
    if (v2 > scale) scale = v2;
    double tol = 1e-12 * scale + 1e-12;

    if (D < -tol) {
        printf("no roots\n");
    } else if (D <= tol) {
        double x = -B / (2.0 * A);
        printf("%.6f\n", fix_zero(x));
