        double sqrtD = sqrt(D);
        double q = -0.5 * (B + copysign(sqrtD, B));
        double x1, x2;
        if (q == 0.0) {
            x1 = (-B - sqrtD) / (2.0 * A);
            x2 = (-B + sqrtD) / (2.0 * A);
        } else {
            x1 = q / A;
            x2 = C / q;
        }
        if (x1 > x2) {
            double tmp = x1;
            x1 = x2;
            x2 = tmp;
        }
        printf("%.6f %.6f\n", fix_zero(x1), fix_zero(x2));
    }

    return 0;
}

