#include <stdio.h>
#include <math.h>
#include <float.h>

static void print_num(long double x) {
    if (x == 0.0L) {
        x = 0.0L;
    }
    if (x < 0.0L && fabsl(x) < 0.5e-6L) {
        x = 0.0L;
    }
    printf("%.6Lf", x);
}

int main(void) {
    long double a, b, c, d, k;
    if (scanf("%Lf %Lf %Lf %Lf %Lf", &a, &b, &c, &d, &k) != 5) {
        return 0;
    }

    long double A = a;
    long double B = b - d;
    long double C = c - k;

    if (A == 0.0L) {
        if (B == 0.0L) {
            printf("no roots\n");
        } else {
            long double x = -C / B;
            print_num(x);
            printf("\n");
        }
        return 0;
    }

    long double D = B * B - 4.0L * A * C;
    long double scale = 1.0L;
    long double v1 = fabsl(B * B);
    long double v2 = fabsl(4.0L * A * C);
    if (v1 > scale) scale = v1;
    if (v2 > scale) scale = v2;
    long double tol = 10.0L * LDBL_EPSILON * scale + 1e-18L;

    if (D < -tol) {
        printf("no roots\n");
    } else if (D <= tol) {
        long double x = -B / (2.0L * A);
        print_num(x);
        printf("\n");
    } else {
        long double sqrtD = sqrtl(D);
        long double sign = (B < 0.0L) ? -1.0L : 1.0L;
        long double q = -0.5L * (B + sign * sqrtD);
        long double x1, x2;

        if (q == 0.0L) {
            x1 = (-B - sqrtD) / (2.0L * A);
            x2 = (-B + sqrtD) / (2.0L * A);
        } else {
            x1 = q / A;
            x2 = C / q;
        }

        if (x1 > x2) {
            long double tmp = x1;
            x1 = x2;
            x2 = tmp;
        }

        print_num(x1);
        printf(" ");
        print_num(x2);
        printf("\n");
    }

    return 0;
}
```

